import React, { useEffect, useState, useRef } from 'react';

interface VirtualInterviewerProps {
  state: 'idle' | 'speaking' | 'listening' | 'thinking' | string;
  onSpeakComplete?: () => void;
}

export default function VirtualInterviewer({ state, onSpeakComplete }: VirtualInterviewerProps) {
  const [mouthOpen, setMouthOpen] = useState(false);
  const [mouthIntensity, setMouthIntensity] = useState(0.5);
  const [isBlinking, setIsBlinking] = useState(false);
  const blinkTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const speakIntervalRef = useRef<NodeJS.Timeout | null>(null);

  // Natural random blinking
  useEffect(() => {
    const scheduleNextBlink = () => {
      const randomDelay = 2000 + Math.random() * 4000; // 2-6 seconds between blinks
      blinkTimeoutRef.current = setTimeout(() => {
        setIsBlinking(true);
        setTimeout(() => setIsBlinking(false), 150); // Blink lasts 150ms
        scheduleNextBlink();
      }, randomDelay);
    };

    scheduleNextBlink();

    return () => {
      if (blinkTimeoutRef.current) clearTimeout(blinkTimeoutRef.current);
    };
  }, []);

  // Mouth animation for speaking state - more natural variation
  useEffect(() => {
    if (state === 'speaking') {
      speakIntervalRef.current = setInterval(() => {
        // Random mouth opening for more natural speech
        const intensity = 0.3 + Math.random() * 0.7;
        setMouthIntensity(intensity);
        setMouthOpen(true);

        setTimeout(() => setMouthOpen(false), 80 + Math.random() * 60);
      }, 120 + Math.random() * 80); // Varying speech rhythm

      return () => {
        if (speakIntervalRef.current) clearInterval(speakIntervalRef.current);
      };
    } else {
      setMouthOpen(false);
      setMouthIntensity(0.5);
    }
  }, [state]);

  const getStateClass = () => {
    switch (state) {
      case 'idle': return 'interviewer-idle';
      case 'speaking': return 'interviewer-speaking';
      case 'listening': return 'interviewer-listening';
      case 'thinking': return 'interviewer-thinking';
      default: return 'interviewer-idle';
    }
  };

  const getStateLabel = () => {
    switch (state) {
      case 'idle': return '😊 Ready';
      case 'speaking': return '🗣️ Speaking...';
      case 'listening': return '👂 Listening...';
      case 'thinking': return '🤔 Thinking...';
      default: return '😊 Ready';
    }
  };

  return (
    <div className="relative w-full h-[500px] bg-gradient-to-b from-gray-800 to-gray-900 rounded-2xl overflow-hidden flex flex-col items-center justify-center">
      {/* State indicator */}
      <div className="absolute top-4 left-1/2 transform -translate-x-1/2 bg-blue-500 text-white px-6 py-2 rounded-full shadow-lg z-10">
        {getStateLabel()}
      </div>

      {/* Interviewer Avatar */}
      <div className={`interviewer-avatar ${getStateClass()}`}>
        {/* Head */}
        <div className="head">
          {/* Hair */}
          <div className="hair"></div>

          {/* Face */}
          <div className="face">
            {/* Eyes */}
            <div className="eyes">
              <div className={`eye left ${isBlinking ? 'blinking' : ''}`}></div>
              <div className={`eye right ${isBlinking ? 'blinking' : ''}`}></div>
            </div>

            {/* Eyebrows */}
            <div className="eyebrows">
              <div className="eyebrow left"></div>
              <div className="eyebrow right"></div>
            </div>

            {/* Nose */}
            <div className="nose"></div>

            {/* Mouth */}
            <div 
              className={`mouth ${mouthOpen ? 'open' : 'closed'}`}
              style={{ 
                height: mouthOpen ? `${8 * mouthIntensity}px` : '4px',
                width: mouthOpen ? `${30 * mouthIntensity}px` : '25px'
              }}
            ></div>
          </div>
        </div>

        {/* Body - Formal business attire */}
        <div className="body">
          {/* Blazer */}
          <div className="blazer"></div>

          {/* Shirt */}
          <div className="shirt"></div>

          {/* Tie */}
          <div className="tie"></div>

          {/* Arms */}
          <div className="arm left"></div>
          <div className="arm right"></div>
        </div>
      </div>

      {/* Instructions */}
      <div className="absolute bottom-4 text-gray-400 text-sm">
        <p>🎧 Use headphones for best experience</p>
      </div>

      <style>{`
        .interviewer-avatar {
          position: relative;
          width: 200px;
          height: 350px;
          transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
        }

        /* IDLE State - Subtle breathing, very minimal */
        .interviewer-idle {
          animation: breathe 4s ease-in-out infinite;
        }

        @keyframes breathe {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-3px); }
        }

        /* SPEAKING State - Subtle head movement, not exaggerated */
        .interviewer-speaking {
          animation: speaking 0.5s ease-in-out infinite;
        }

        @keyframes speaking {
          0%, 100% { transform: translateY(0) rotate(-0.5deg); }
          50% { transform: translateY(-2px) rotate(0.5deg); }
        }

        /* LISTENING State - Attentive, slight forward lean */
        .interviewer-listening {
          animation: listen 3s ease-in-out infinite;
        }

        @keyframes listen {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-1px) rotate(0.3deg); }
        }

        /* THINKING State - Subtle head tilt, contemplative */
        .interviewer-thinking {
          animation: think 2s ease-in-out infinite;
        }

        @keyframes think {
          0%, 100% { transform: rotate(0deg); }
          50% { transform: rotate(2deg); }
        }

        /* Head */
        .head {
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 120px;
          height: 140px;
          transition: transform 0.4s ease;
        }

        .hair {
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 110px;
          height: 60px;
          background: #2c1810;
          border-radius: 60px 60px 0 0;
        }

        .face {
          position: absolute;
          top: 30px;
          left: 50%;
          transform: translateX(-50%);
          width: 100px;
          height: 110px;
          background: #e0ac69;
          border-radius: 50px;
        }

        /* Eyes */
        .eyes {
          position: absolute;
          top: 35px;
          left: 50%;
          transform: translateX(-50%);
          width: 70px;
          display: flex;
          justify-content: space-between;
        }

        .eye {
          width: 18px;
          height: 18px;
          background: white;
          border-radius: 50%;
          position: relative;
          transition: transform 0.15s ease;
        }

        .eye.blinking {
          transform: scaleY(0.1);
        }

        .eye::after {
          content: '';
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          width: 8px;
          height: 8px;
          background: #2c1810;
          border-radius: 50%;
        }

        /* Eyebrows */
        .eyebrows {
          position: absolute;
          top: 25px;
          left: 50%;
          transform: translateX(-50%);
          width: 60px;
          display: flex;
          justify-content: space-between;
        }

        .eyebrow {
          width: 20px;
          height: 4px;
          background: #2c1810;
          border-radius: 2px;
          transition: transform 0.3s ease;
        }

        /* Nose */
        .nose {
          position: absolute;
          top: 50px;
          left: 50%;
          transform: translateX(-50%);
          width: 12px;
          height: 20px;
          background: #d4a05a;
          border-radius: 6px;
        }

        /* Mouth */
        .mouth {
          position: absolute;
          top: 80px;
          left: 50%;
          transform: translateX(-50%);
          background: #c4785a;
          border-radius: 15px;
          transition: all 0.08s ease;
        }

        /* Body */
        .body {
          position: absolute;
          top: 130px;
          left: 50%;
          transform: translateX(-50%);
          width: 140px;
          height: 220px;
        }

        /* Blazer */
        .blazer {
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 140px;
          height: 200px;
          background: #1a1a2e;
          border-radius: 10px 10px 0 0;
        }

        /* Shirt */
        .shirt {
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 60px;
          height: 80px;
          background: white;
          border-radius: 5px 5px 0 0;
        }

        /* Tie */
        .tie {
          position: absolute;
          top: 10px;
          left: 50%;
          transform: translateX(-50%);
          width: 15px;
          height: 70px;
          background: #8b0000;
          clip-path: polygon(50% 0%, 0% 100%, 100% 100%);
        }

        /* Arms */
        .arm {
          position: absolute;
          top: 20px;
          width: 30px;
          height: 150px;
          background: #1a1a2e;
          border-radius: 15px;
          transition: transform 0.4s ease;
        }

        .arm.left {
          left: -20px;
          transform: rotate(10deg);
        }

        .arm.right {
          right: -20px;
          transform: rotate(-10deg);
        }

        /* State-specific subtle animations */
        .interviewer-listening .arm.left {
          animation: listenArm 3s ease-in-out infinite;
        }

